import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BLaSdaBb.js";const n="/screens/relations.png",s="/screens/parley.png",c=JSON.parse('{"title":"Diplomacy & Trade","description":"","frontmatter":{},"headers":[],"relativePath":"guide/diplomacy.md","filePath":"guide/diplomacy.md"}'),i={name:"guide/diplomacy.md"};function d(l,e,h,u,g,m){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="diplomacy-trade" tabindex="-1">Diplomacy &amp; Trade <a class="header-anchor" href="#diplomacy-trade" aria-label="Permalink to &quot;Diplomacy &amp; Trade&quot;">​</a></h1><h2 id="guild-relations" tabindex="-1">Guild relations <a class="header-anchor" href="#guild-relations" aria-label="Permalink to &quot;Guild relations&quot;">​</a></h2><p><img src="'+n+'" alt="Guild relations"></p><p><em>Shows the opinion of each guild toward you. Red (Loathing) means hostility, blue (Empathy) unlocks better trade options, gold (Devotion) means they&#39;re your ally.</em></p><p>Every other guild holds an opinion of you, from <strong>Loathing</strong> to <strong>Devotion</strong>. Attacks and captures sour it; gifts of gold sweeten it. Guilds that bear you <strong>no grudge</strong> leave your lands alone. War is something you earn, by drawn blades and sour demands. Nobody begins as your enemy, and there is no guild you cannot win over. Entropy answers to none of it: its armies never range beyond the creeping edge of the blight, but where the rot has reached, they spare no one.</p><h3 id="relation-thresholds" tabindex="-1">Relation Thresholds <a class="header-anchor" href="#relation-thresholds" aria-label="Permalink to &quot;Relation Thresholds&quot;">​</a></h3><p>As a guild&#39;s opinion of you changes, new options unlock:</p><table tabindex="0"><thead><tr><th>Opinion</th><th>Can they do</th><th>What you can do</th></tr></thead><tbody><tr><td><strong>Loathing</strong> (red)</td><td>Attack you freely</td><td>Nothing yet; keep gifting</td></tr><tr><td><strong>Neutral</strong> (grey)</td><td>Leave you alone</td><td>Send gifts; slowly warm them</td></tr><tr><td><strong>Empathy</strong> (blue)</td><td>Proposed trades still ignored</td><td><strong>Parley opens</strong>: give gifts to warm them more</td></tr><tr><td><strong>Devotion</strong> (gold)</td><td>Actively avoid you</td><td><strong>Full barter unlocks</strong>: propose any deal, both sides offer/request</td></tr></tbody></table><p><strong>Auto-trades:</strong> Even without contact, guilds trade among themselves. A neighbor may have better resources than you simply because they have a better arrangement with someone else.</p><h2 id="raising-the-fallen" tabindex="-1">Raising the fallen <a class="header-anchor" href="#raising-the-fallen" aria-label="Permalink to &quot;Raising the fallen&quot;">​</a></h2><p>When a guild falls, to Entropy or to anyone else, its cities go dark. Take a fallen guild&#39;s <strong>capital city</strong> and you&#39;ll be offered a choice: keep the walls, or <strong>hand the capital back</strong>. Returned, the guild rises again with a fresh Lord and a seeded treasury. They come back at <strong>Devotion</strong>, remembering who raised them, and another banner stands between you and the blight.</p><h2 id="envoys-at-your-door" tabindex="-1">Envoys at your door <a class="header-anchor" href="#envoys-at-your-door" aria-label="Permalink to &quot;Envoys at your door&quot;">​</a></h2><p>Trade is not something only you propose. A guild that is short of one thing and sitting on another will <strong>send an envoy to you</strong> with a deal already written: so much of theirs for so much of yours. Take it and the goods change hands at once, and they warm to you a little. Turn it away and nothing moves. Refusing is not an insult.</p><p>They deal among themselves the same way, whether you ever hear of it or not. A neighbour who never seems to run out of bread may simply have a better arrangement with somebody than you do.</p><h2 id="parley-barter" tabindex="-1">Parley &amp; barter <a class="header-anchor" href="#parley-barter" aria-label="Permalink to &quot;Parley &amp; barter&quot;">​</a></h2><p><img src="'+s+'" alt="The envoy audience"></p><p><em>Build a deal by offering/requesting resources from both sides. The scale shows whether they think it&#39;s <em>Insulting</em>, <em>Stingy</em>, <em>Fair</em>, or <em>Generous</em>. Your stance (Plea/Request/Demand) affects how much you can ask.</em></p><p><strong>Parley</strong> opens an audience with another guild&#39;s lord. Gifts always work; full <strong>barter</strong> opens once they feel Empathy toward you. Build a deal from both ledgers, what you offer against what you request, and watch the scale: they&#39;ll call it <em>Insulting</em>, <em>Stingy</em>, <em>Fair</em> or <em>Generous</em>.</p><p>Your <strong>stance</strong> matters too. A <em>Plea</em> needs the sweetest deal, a <em>Request</em> is the honest middle, and a <em>Demand</em> extracts more but sours their opinion whether or not they accept. Generous deals warm it.</p>',19)])])}const p=t(i,[["render",d]]);export{c as __pageData,p as default};
